文章的概述！显示在首页位置Gin 



Introduction to Gin Web Framework
Gin 是一个用 Go(Golang) 编写的 HTTP web 框架

具有高性能的优点，其性能比普通HTTP web 框架(httprouter)提高了近40倍

gin设计简单，性能高效，无论是简单还是复杂的web系统，用起来都非常顺手

入门容易

可以通过gin构建很丰富的应用

Go语言常用web框架

Gin
buffalo
beego
echo
iris
revel









Get Requestpackage mainimport (	&quot;github.com/gin-gonic/gin&quot;	&quot;net/http&quot;)func main() &#123;	//获取路由引擎	engine := gin.Default()	//指定请求路由，方法，请求处理函数	engine.GET(&quot;/getReq&quot;, getReq)	//启动服务	engine.Run(&quot;:9000&quot;)&#125;func getReq(context *gin.Context) &#123;	//获取请求url中的参数	name := context.Query(&quot;name&quot;)	//以字符串方式返回结果	// context.String(http.StatusOK, &quot;hello ! &quot;+name)  //以JSON格式返回结果	context.JSON(http.StatusOK, gin.H&#123;		&quot;status&quot;: http.StatusOK,		&quot;msg&quot;:    &quot;response Data&quot;,		&quot;data&quot;:   &quot;hello !!!&quot; + name,	&#125;)&#125;







Post Requestpackage mainimport (	&quot;github.com/gin-gonic/gin&quot;	&quot;net/http&quot;)func main() &#123;	engine := gin.Default()	engine.POST(&quot;/postReq&quot;, postReq)	engine.Run(&quot;:9000&quot;)&#125;func postReq(context *gin.Context) &#123;	//从表单中获取参数，并可以设置默认值	// name := context.DefaultPostForm(&quot;name&quot;,&quot;default value&quot;)	//从表单中获取参数，如果存在则返回 值,true ,否则 &quot;&quot;,false	name, b := context.GetPostForm(&quot;name&quot;)	context.String(http.StatusOK, &quot;hello post &quot;+name)&#125;







Redirectpackage mainimport (	&quot;github.com/gin-gonic/gin&quot;	&quot;net/http&quot;)func main() &#123;	r := gin.Default()	//重定向到外部网络	r.GET(&quot;/redirect1&quot;, func(c *gin.Context) &#123;		c.Redirect(http.StatusMovedPermanently, &quot;http://www.baidu.com&quot;)	&#125;)  //重定向到本地路由	r.GET(&quot;redirect2&quot;, func(c *gin.Context) &#123;		c.Request.URL.Path = &quot;/testRedirect&quot;		r.HandleContext(c)	&#125;)	r.GET(&quot;/testRedirect&quot;, func(c *gin.Context) &#123;		c.String(http.StatusOK, &quot;hello Redirect&quot;)	&#125;)	r.Run(&quot;:9000&quot;)&#125;







Get Other Data（返回第三方获取的数据）package mainimport (	&quot;github.com/gin-gonic/gin&quot;	&quot;net/http&quot;)func main() &#123;	engine := gin.Default()	engine.GET(&quot;/getOtherData&quot;, func(c *gin.Context) &#123;		url := &quot;https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRfneGKpEWbkR7MBmgENqFm2h0tyh2mf3uV-w&amp;s&quot;    //请求外部接口，获取数据    response, err := http.Get(url)		if err != nil || response.StatusCode != http.StatusOK &#123;			//应答			c.Status(http.StatusServiceUnavailable)			return		&#125;		body := response.Body		contentLength := response.ContentLength		contentType := response.Header.Get(&quot;Content-Type&quot;)		c.DataFromReader(http.StatusOK, contentLength, contentType, body, nil)	&#125;)	engine.Run(&quot;:9000&quot;)&#125;







多形式渲染（响应不同格式的数据）package mainimport (	&quot;github.com/gin-gonic/gin&quot;	&quot;net/http&quot;)func main() &#123;	r := gin.Default()	//返回JSON格式的数据	r.GET(&quot;/json&quot;, func(c *gin.Context) &#123;		c.JSON(http.StatusOK, gin.H&#123;			&quot;data&quot;: &quot;&lt;h1&gt;这是json格式的响应&lt;/h1&gt;&quot;,		&#125;)	&#125;)	//原样输出html格式数据	r.GET(&quot;/html&quot;, func(c *gin.Context) &#123;		c.PureJSON(http.StatusOK, gin.H&#123;			&quot;data&quot;: &quot;&lt;h1&gt;原样输出html格式数据&lt;/h1&gt;&quot;,		&#125;)	&#125;)	//返回XML格式数据	r.GET(&quot;/xml&quot;, func(c *gin.Context) &#123;		type Message struct &#123;			Name string			Data string			Age  int		&#125;		info := Message&#123;&#125;		info.Name = &quot;张三&quot;		info.Data = &quot;返回xml格式的数据&quot;		info.Age = 48		c.XML(http.StatusOK, info)	&#125;)	//返回yaml格式数据	r.GET(&quot;/yaml&quot;, func(c *gin.Context) &#123;		c.YAML(http.StatusOK, gin.H&#123;			&quot;name&quot;: &quot;lisi&quot;,			&quot;age&quot;:  18,			&quot;data&quot;: &quot;响应yaml格式的数据&quot;,		&#125;)	&#125;)	r.Run(&quot;:9000&quot;)&#125;







文件服务器package mainimport (	&quot;github.com/gin-gonic/gin&quot;)func main() &#123;	r := gin.Default()	r.GET(&quot;/fileServer&quot;, func(c *gin.Context) &#123;		path := &quot;D:/ws2025/ws-stu/gin-stu-wangyiyunketang/&quot;		fileName := c.Query(&quot;name&quot;)		c.File(path + fileName)	&#125;)	r.Run(&quot;:9000&quot;)&#125;







文件上传单文件上传package mainimport (	&quot;github.com/gin-gonic/gin&quot;	&quot;net/http&quot;)func main() &#123;	engine := gin.Default()	engine.POST(&quot;/fileUpload&quot;, func(c *gin.Context) &#123;		file, err := c.FormFile(&quot;fileName&quot;)		if err != nil &#123;			c.String(http.StatusBadRequest, &quot;file upload err!&quot;)		&#125;		path := &quot;D:/ws2025/ws-stu/gin-stu-wangyiyunketang/&quot;		c.SaveUploadedFile(file, path+file.Filename)		c.String(http.StatusOK, &quot;%s upload finished !&quot;,file.Filename)	&#125;)	engine.Run(&quot;:9000&quot;)&#125;







多文件上传package mainimport (	&quot;fmt&quot;	&quot;github.com/gin-gonic/gin&quot;	&quot;net/http&quot;)func main() &#123;	r := gin.Default()	r.POST(&quot;/filesUpload&quot;, func(c *gin.Context) &#123;		form, err := c.MultipartForm()		if err != nil &#123;			c.String(http.StatusBadRequest, &quot;files upload error!!&quot;)		&#125;		files := form.File[&quot;filesKey&quot;]		path := &quot;D:/ws2025/ws-stu/gin-stu-wangyiyunketang/files/&quot;		for _, file := range files &#123;			c.SaveUploadedFile(file, path+file.Filename)			fmt.Println(&quot;file &quot; + file.Filename + &quot;\t uploaded!&quot;)		&#125;		c.String(http.StatusOK, fmt.Sprintf(&quot;%d number files uploaded finished!&quot;, len(files)))	&#125;)	r.Run(&quot;:9000&quot;)&#125;

















